export default function makeController() {
  let prevVel = null, prevAtt = null, prevThrust = 0.5;
  let distX = 0, distZ = 0, distY = 0;
  let estMass = 0.78;
  let targetIndex = -1, phase = 'align', settle = 0;
  let vzFilt = 0, vyFilt = 0, vxFilt = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      vxFilt += 0.35 * (v.x - vxFilt);
      vyFilt += 0.35 * (v.y - vyFilt);
      vzFilt += 0.35 * (v.z - vzFilt);

      if (prevVel !== null && obs.t > 0.08 && p.y > 0.12) {
        const ax_meas = (v.x - prevVel.x) / dt;
        const ay_meas = (v.y - prevVel.y) / dt;
        const az_meas = (v.z - prevVel.z) / dt;

        const bodyX = Math.sin(prevAtt.pitch) * Math.cos(prevAtt.roll);
        const bodyZ = -Math.sin(prevAtt.roll);
        const dirX = Math.cos(prevAtt.yaw) * bodyX + Math.sin(prevAtt.yaw) * bodyZ;
        const dirY = Math.cos(prevAtt.pitch) * Math.cos(prevAtt.roll);
        const dirZ = -Math.sin(prevAtt.yaw) * bodyX + Math.cos(prevAtt.yaw) * bodyZ;

        const specThrust = (prevThrust * 16.0 * 0.9) / estMass;
        const ax_model = specThrust * dirX - (0.42 / estMass) * v.x;
        const ay_model = specThrust * dirY - 9.81 - (0.42 / estMass) * v.y;
        const az_model = specThrust * dirZ - (0.42 / estMass) * v.z;

        const alpha = 0.25;
        distX = clamp(distX + alpha * ((ax_meas - ax_model) - distX), -8.0, 8.0);
        distY = clamp(distY + alpha * ((ay_meas - ay_model) - distY), -5.0, 5.0);
        distZ = clamp(distZ + alpha * ((az_meas - az_model) - distZ), -8.0, 8.0);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };

      let target;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        const vy = Math.abs(vyFilt);
        const vz = Math.abs(vzFilt);

        if (phase === 'align') {
          const approachX = gate.x - 0.35;
          target = { x: approachX, y: gate.y, z: gate.z };
          // Predict z and y at crossing (~0.18s ahead)
          const predZ = Math.abs((p.z + vzFilt * 0.12) - gate.z);
          const predY = Math.abs((p.y + vyFilt * 0.12) - gate.y);
          if (p.x > gate.x - 0.50 && dy < 0.06 && dz < 0.018 && predZ < 0.020 && predY < 0.07 && vy < 0.25 && vz < 0.14) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) phase = 'cross';
        }
        if (phase === 'cross') {
          target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
          const dtCross = Math.max(0.02, (gate.x - p.x) / Math.max(0.4, v.x));
          const predZ = Math.abs((p.z + vzFilt * Math.min(0.18, dtCross)) - gate.z);
          const predY = Math.abs((p.y + vyFilt * Math.min(0.18, dtCross)) - gate.y);
          if (p.x < gate.x - 0.08 && (dy > 0.09 || dz > 0.024 || predZ > 0.028 || predY > 0.10)) {
            phase = 'align';
            settle = 0;
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distHoriz = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(vxFilt, vzFilt);
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach_pad';
          settle = 0;
        }
        if (phase === 'approach_pad') {
          target = { x: pad.x, y: 0.35, z: pad.z };
          if (distHoriz < 0.09 && speedHoriz < 0.22 && p.y < 0.50) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) phase = 'descend';
        }
        if (phase === 'descend') {
          if (distHoriz > 0.13 && p.y > 0.12) {
            phase = 'approach_pad';
            settle = 0;
            target = { x: pad.x, y: 0.30, z: pad.z };
          } else {
            // Smooth descent target
            const targetY = distHoriz < 0.10 ? 0.04 : 0.14;
            target = { x: pad.x, y: targetY, z: pad.z };
          }
        }
      }

      const ex = clamp(target.x - p.x, -0.75, 0.75);
      const ey = clamp(target.y - p.y, -0.75, 0.75);
      const ez = clamp(target.z - p.z, -0.75, 0.75);

      let kp_x = 5.5, kd_x = 4.2;
      let kp_z = 9.0, kd_z = 5.5;
      let kp_y = 8.5, kd_y = 5.2;

      if (obs.gateIndex < 3) {
        kp_z = 11.5; kd_z = 6.2;
        kp_y = 9.5; kd_y = 5.5;
        if (phase === 'cross') {
          kp_x = 6.5; kd_x = 4.0;
        }
      }

      const ax_des = kp_x * ex - kd_x * v.x - distX + (0.42 / estMass) * v.x;
      const az_des = kp_z * ez - kd_z * v.z - distZ + (0.42 / estMass) * v.z;
      let ay_des = kp_y * ey - kd_y * v.y - distY + (0.42 / estMass) * v.y;

      if (phase === 'descend' && p.y < 0.15) {
        ay_des = clamp(ay_des, -3.5, 2.5);
      } else {
        ay_des = clamp(ay_des, -5.0, 5.5);
      }

      // Limit horizontal acceleration during climb from floor so thrust stays below saturation
      let maxHorizAcc = p.y < 0.25 ? 2.5 : 4.5;
      if (phase === 'descend' && p.y < 0.13) {
        // Must keep roll/pitch < 0.18 rad when touching floor and holding
        maxHorizAcc = 1.65;
      }
      const ax_lim = clamp(ax_des, -maxHorizAcc, maxHorizAcc);
      const az_lim = clamp(az_des, -maxHorizAcc, maxHorizAcc);

      const total_ay = Math.max(3.5, 9.81 + ay_des);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const a_fwd = cy * ax_lim - sy * az_lim;
      const a_lat = sy * ax_lim + cy * az_lim;
      const a_norm = Math.hypot(a_fwd, total_ay, a_lat);

      let maxTilt = 0.45;
      if (p.y < 0.20 && obs.t < 0.6) maxTilt = 0.25;
      if (phase === 'descend' && p.y < 0.13) maxTilt = 0.165;

      const sinRoll = clamp(-a_lat / a_norm, -Math.sin(maxTilt), Math.sin(maxTilt));
      let roll = Math.asin(sinRoll);
      const sinPitch = clamp(a_fwd / (a_norm * Math.cos(roll)), -Math.sin(maxTilt), Math.sin(maxTilt));
      let pitch = Math.asin(sinPitch);

      const tiltFactor = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp((estMass * total_ay) / (16.0 * 0.9 * tiltFactor), 0, 0.78);
      if (phase === 'descend' && p.y <= 0.088 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.13 && Math.abs(v.y) < 0.35) {
        thrust = 0.12;
        roll = clamp(roll, -0.15, 0.15);
        pitch = clamp(pitch, -0.15, 0.15);
      }

      prevThrust = thrust;
      const yawRate = clamp(-3.0 * att.yaw - 0.5 * obs.rates.yaw, -2, 2);
      return { thrust, roll: clamp(roll, -0.6, 0.6), pitch: clamp(pitch, -0.6, 0.6), yawRate };
    }
  };
}

