export default function makeController() {
  let prevVel = null, prevThrust = 0.5;
  let motorThrust = 0.5;
  let distX = 0, distZ = 0, distY = 0;
  let intX = 0, intY = 0, intZ = 0;
  let estMass = 0.78;
  let targetIndex = -1, phase = 'align', settle = 0;
  let vxF = 0, vyF = 0, vzF = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      vxF += 0.4 * (v.x - vxF);
      vyF += 0.4 * (v.y - vyF);
      vzF += 0.4 * (v.z - vzF);

      // Model motor lag (~0.04s)
      motorThrust += (prevThrust - motorThrust) * (1 - Math.exp(-dt / 0.04));

      if (prevVel !== null && obs.t > 0.06 && p.y > 0.11) {
        const ax_meas = (v.x - prevVel.x) / dt;
        const ay_meas = (v.y - prevVel.y) / dt;
        const az_meas = (v.z - prevVel.z) / dt;

        const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
        const bodyZ = -Math.sin(att.roll);
        const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
        const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
        const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

        // First estimate effective vertical thrust / mass from vertical motion when not saturated
        if (motorThrust > 0.25 && motorThrust < 0.75 && dirY > 0.75) {
          const meas_spec = (ay_meas + 9.81 + (0.42 / estMass) * v.y) / (motorThrust * 16.0 * 0.9 * dirY);
          if (meas_spec > 0.7 && meas_spec < 1.8) {
            const m_obs = clamp(1.0 / meas_spec, 0.55, 1.05);
            estMass += 0.04 * (m_obs - estMass);
          }
        }

        const specThrust = (motorThrust * 16.0 * 0.9) / estMass;
        const ax_model = specThrust * dirX - (0.42 / estMass) * v.x;
        const ay_model = specThrust * dirY - 9.81 - (0.42 / estMass) * v.y;
        const az_model = specThrust * dirZ - (0.42 / estMass) * v.z;

        const alpha = 0.28;
        distX = clamp(distX + alpha * ((ax_meas - ax_model) - distX), -7.5, 7.5);
        distY = clamp(distY + alpha * ((ay_meas - ay_model) - distY), -4.0, 4.0);
        distZ = clamp(distZ + alpha * ((az_meas - az_model) - distZ), -7.5, 7.5);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };

      let target;
      let vx_ref = 0, vy_ref = 0, vz_ref = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
          intZ *= 0.5;
          intX *= 0.5;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        const vy = Math.abs(vyF);
        const vz = Math.abs(vzF);

        if (phase === 'align') {
          const approachX = gate.x - 0.32;
          target = { x: approachX, y: gate.y, z: gate.z };
          const predZ = Math.abs((p.z + vzF * 0.12) - gate.z);
          const predY = Math.abs((p.y + vyF * 0.12) - gate.y);
          if (p.x > gate.x - 0.55 && dy < 0.065 && dz < 0.019 && predZ < 0.023 && predY < 0.075 && vy < 0.30 && vz < 0.16) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 3) phase = 'cross';
        }
        if (phase === 'cross') {
          target = { x: gate.x + 0.35, y: gate.y, z: gate.z };
          vx_ref = 0.65;
          const dtCross = clamp((gate.x - p.x) / Math.max(0.35, vxF), 0.02, 0.18);
          const predZ = Math.abs((p.z + vzF * dtCross) - gate.z);
          const predY = Math.abs((p.y + vyF * dtCross) - gate.y);
          if (p.x < gate.x - 0.07 && (dy > 0.095 || dz > 0.025 || predZ > 0.029 || predY > 0.105)) {
            phase = 'align';
            settle = 0;
            vx_ref = 0;
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distHoriz = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(vxF, vzF);
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach_pad';
          settle = 0;
        }
        if (phase === 'approach_pad') {
          target = { x: pad.x, y: 0.32, z: pad.z };
          if (distHoriz < 0.11 && speedHoriz < 0.28 && p.y < 0.55) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 3) phase = 'descend';
        }
        if (phase === 'descend') {
          if (distHoriz > 0.14 && p.y > 0.13) {
            phase = 'approach_pad';
            settle = 0;
            target = { x: pad.x, y: 0.28, z: pad.z };
          } else {
            const targetY = distHoriz < 0.11 ? 0.04 : 0.13;
            target = { x: pad.x, y: targetY, z: pad.z };
          }
        }
      }

      const ex_raw = target.x - p.x;
      const ey_raw = target.y - p.y;
      const ez_raw = target.z - p.z;

      if (Math.abs(ex_raw) < 0.35 && p.y > 0.12) intX = clamp(intX + ex_raw * dt, -0.35, 0.35);
      if (Math.abs(ey_raw) < 0.35 && p.y > 0.12) intY = clamp(intY + ey_raw * dt, -0.35, 0.35);
      if (Math.abs(ez_raw) < 0.35 && p.y > 0.12) intZ = clamp(intZ + ez_raw * dt, -0.35, 0.35);

      const ex = clamp(ex_raw, -0.75, 0.75);
      const ey = clamp(ey_raw, -0.75, 0.75);
      const ez = clamp(ez_raw, -0.75, 0.75);

      let kp_x = 6.5, kd_x = 4.6, ki_x = 3.5;
      let kp_z = 11.5, kd_z = 6.2, ki_z = 5.5;
      let kp_y = 9.0, kd_y = 5.2, ki_y = 3.0;

      if (obs.gateIndex < 3 && phase === 'cross') {
        kp_z = 13.5; kd_z = 6.8;
        kp_x = 7.5; kd_x = 4.4;
      }

      const ax_des = kp_x * ex + kd_x * (vx_ref - v.x) + ki_x * intX - distX + (0.42 / estMass) * v.x;
      const az_des = kp_z * ez + kd_z * (vz_ref - v.z) + ki_z * intZ - distZ + (0.42 / estMass) * v.z;
      let ay_des = kp_y * ey + kd_y * (vy_ref - v.y) + ki_y * intY - distY + (0.42 / estMass) * v.y;

      if (phase === 'descend' && p.y < 0.16) {
        ay_des = clamp(ay_des, -3.5, 2.5);
      } else {
        ay_des = clamp(ay_des, -5.0, 5.5);
      }

      let maxHorizAcc = (p.y < 0.25 && obs.t < 0.6) ? 2.8 : 5.2;
      if (phase === 'descend' && p.y < 0.13) {
        maxHorizAcc = 1.65;
      }
      const ax_lim = clamp(ax_des, -maxHorizAcc, maxHorizAcc);
      const az_lim = clamp(az_des, -maxHorizAcc, maxHorizAcc);

      const total_ay = Math.max(3.5, 9.81 + ay_des);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const a_fwd = cy * ax_lim - sy * az_lim;
      const a_lat = sy * ax_lim + cy * az_lim;
      const a_norm = Math.hypot(a_fwd, total_ay, a_lat);

      let maxTilt = 0.48;
      if (p.y < 0.20 && obs.t < 0.5) maxTilt = 0.28;
      if (phase === 'descend' && p.y < 0.13) maxTilt = 0.165;

      const sinRoll = clamp(-a_lat / a_norm, -Math.sin(maxTilt), Math.sin(maxTilt));
      let roll = Math.asin(sinRoll);
      const sinPitch = clamp(a_fwd / (a_norm * Math.cos(roll)), -Math.sin(maxTilt), Math.sin(maxTilt));
      let pitch = Math.asin(sinPitch);

      const tiltFactor = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp((estMass * total_ay) / (16.0 * 0.9 * tiltFactor), 0, 0.80);
      if (phase === 'descend' && p.y <= 0.088 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.13 && Math.abs(v.y) < 0.35) {
        thrust = 0.10;
        roll = clamp(roll, -0.15, 0.15);
        pitch = clamp(pitch, -0.15, 0.15);
      }

      prevThrust = thrust;
      const yawRate = clamp(-3.0 * att.yaw - 0.5 * obs.rates.yaw, -2, 2);
      return { thrust, roll: clamp(roll, -0.6, 0.6), pitch: clamp(pitch, -0.6, 0.6), yawRate };
    }
  };
}

