        const az_model = specThrust * dirZ - (0.42 / estMass) * v.z;

        const alpha = 0.12;
        distX = clamp(distX + alpha * ((ax_meas - ax_model) - distX), -6.0, 6.0);
        distY = clamp(distY + alpha * ((ay_meas - ay_model) - distY), -4.0, 4.0);
        distZ = clamp(distZ + alpha * ((az_meas - az_model) - distZ), -6.0, 6.0);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };

      let target;
      let vx_ref = 0;

