      let roll = Math.asin(sinRoll);
      const sinPitch = clamp(a_fwd / (a_norm * Math.cos(roll)), -Math.sin(maxTilt), Math.sin(maxTilt));
      let pitch = Math.asin(sinPitch);

      const tiltFactor = Math.max(0.6, Math.cos(att.roll) * Math.cos(att.pitch));
