export default function makeController() {
  let prevVel = null;
  let estRoll = 0, estPitch = 0, estSpec = 9.81 / 0.55;
  let distX = 0, distZ = 0, distY = 0;
  let estMass = 0.78;
  let targetIndex = -1, phase = 'align', settle = 0;
  let vzFilt = 0, vyFilt = 0, vxFilt = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      vxFilt += 0.35 * (v.x - vxFilt);
      vyFilt += 0.35 * (v.y - vyFilt);
      vzFilt += 0.35 * (v.z - vzFilt);

      if (prevVel !== null && obs.t > 0.12 && p.y > 0.14) {
        const ax_meas = (v.x - prevVel.x) / dt;
        const ay_meas = (v.y - prevVel.y) / dt;
        const az_meas = (v.z - prevVel.z) / dt;

        const bodyX = Math.sin(estPitch) * Math.cos(estRoll);
        const bodyZ = -Math.sin(estRoll);
        const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
        const dirY = Math.cos(estPitch) * Math.cos(estRoll);
        const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

        // Actual vertical acceleration gives us actual specific thrust when airborne
        const actual_spec = clamp((ay_meas + 9.81 + (0.42 / estMass) * v.y) / Math.max(0.6, dirY), 2.0, 22.0);
        const ax_model = actual_spec * dirX - (0.42 / estMass) * v.x;
        const ay_model = estSpec * dirY - 9.81 - (0.42 / estMass) * v.y;
        const az_model = actual_spec * dirZ - (0.42 / estMass) * v.z;

        const alpha = 0.08;
        distX = clamp(distX + alpha * ((ax_meas - ax_model) - distX), -5.0, 5.0);
        distY = clamp(distY + 0.05 * ((ay_meas - ay_model) - distY), -3.5, 3.5);
        distZ = clamp(distZ + alpha * ((az_meas - az_model) - distZ), -5.0, 5.0);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };
      estRoll += 0.35 * (att.roll - estRoll);
      estPitch += 0.35 * (att.pitch - estPitch);

      let target;
      let vx_ref = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        const vy = Math.abs(vyFilt);
        const vz = Math.abs(vzFilt);

        const distToGateX = Math.max(0, gate.x - p.x);
        const tToGate = clamp(distToGateX / Math.max(0.45, vxFilt), 0.03, 0.20);
        const predZ = Math.abs((p.z + vzFilt * tToGate) - gate.z);
        const predY = Math.abs((p.y + vyFilt * tToGate) - gate.y);

        if (phase === 'align') {
          const approachX = gate.x - 0.36;
          target = { x: approachX, y: gate.y, z: gate.z };
          if (p.x > gate.x - 0.55 && dy < 0.075 && dz < 0.022 && predZ < 0.025 && predY < 0.085 && vy < 0.32 && vz < 0.18) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 4) phase = 'cross';
        }
        if (phase === 'cross') {
          target = { x: gate.x + 0.38, y: gate.y, z: gate.z };
          vx_ref = 0.65;
          if (p.x < gate.x - 0.08 && (dy > 0.105 || dz > 0.027 || predZ > 0.031)) {
            phase = 'align';
            settle = 0;
            vx_ref = 0;
            target = { x: gate.x - 0.36, y: gate.y, z: gate.z };
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distHoriz = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(vxFilt, vzFilt);
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach_pad';
        }
        if (phase === 'approach_pad') {
          target = { x: pad.x, y: 0.40, z: pad.z };
          if (distHoriz < 0.12 && speedHoriz < 0.28 && p.y < 0.58) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          if (distHoriz > 0.15 && p.y > 0.13) {
            phase = 'approach_pad';
            target = { x: pad.x, y: 0.35, z: pad.z };
          } else {
            target = { x: pad.x, y: 0.04, z: pad.z };
          }
        }
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      let kp_x = 5.2, kd_x = 4.0;
      let kp_z = 7.5, kd_z = 5.0;
      let kp_y = 7.5, kd_y = 4.8;

      if (obs.gateIndex < 3 && phase === 'cross') {
        kp_z = 9.0; kd_z = 5.5;
        kp_y = 8.5; kd_y = 5.2;
      }

      const ax_des = kp_x * ex + kd_x * (vx_ref - v.x) - distX + (0.42 / estMass) * v.x;
      const az_des = kp_z * ez - kd_z * v.z - distZ + (0.42 / estMass) * v.z;
      let ay_des = kp_y * ey - kd_y * v.y - distY + (0.42 / estMass) * v.y;

      if (phase === 'descend' && p.y < 0.16) {
        ay_des = clamp(ay_des, -3.5, 2.0);
      } else {
        ay_des = clamp(ay_des, -4.5, 4.5);
      }

      const total_ay = Math.max(2.5, 9.81 + ay_des);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const a_fwd = cy * ax_des - sy * az_des;
      const a_lat = sy * ax_des + cy * az_des;
      const a_norm = Math.hypot(a_fwd, total_ay, a_lat);

      let maxTilt = 0.45;
      if (obs.t < 0.5 && p.y < 0.30) maxTilt = 0.25;
      if (phase === 'descend' && p.y < 0.14) maxTilt = 0.16;

      const sinRoll = clamp(-a_lat / a_norm, -Math.sin(maxTilt), Math.sin(maxTilt));
      let roll = Math.asin(sinRoll);
      const sinPitch = clamp(a_fwd / (a_norm * Math.cos(roll)), -Math.sin(maxTilt), Math.sin(maxTilt));
      let pitch = Math.asin(sinPitch);

      const tiltFactor = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp((estMass * total_ay) / (16.0 * 0.9 * tiltFactor), 0, 0.72);
      if (phase === 'descend' && p.y <= 0.088 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) < 0.13 && Math.abs(v.y) < 0.30) {
        thrust = 0.12;
        roll = clamp(roll, -0.15, 0.15);
        pitch = clamp(pitch, -0.15, 0.15);
      }

      estSpec += 0.25 * (((thrust * 16.0 * 0.9) / estMass) - estSpec);
      const yawRate = clamp(-3.0 * att.yaw - 0.5 * obs.rates.yaw, -2, 2);
      return { thrust, roll: clamp(roll, -0.6, 0.6), pitch: clamp(pitch, -0.6, 0.6), yawRate };
    }
  };
}

