export default function makeController() {
  let prevVel = null, prevAtt = null, prevThrust = 0.52;
  let estSpec = 9.81 / 0.55;
  let distX = 0, distZ = 0, distY = 0;
  let estMass = 0.78;
  let targetIndex = -1, phase = 'align', settle = 0;
  let vzFilt = 0, vyFilt = 0, vxFilt = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      vxFilt += 0.4 * (v.x - vxFilt);
      vyFilt += 0.4 * (v.y - vyFilt);
      vzFilt += 0.4 * (v.z - vzFilt);

      if (prevVel !== null && obs.t > 0.10 && p.y > 0.13) {
        const ax_meas = (v.x - prevVel.x) / dt;
        const ay_meas = (v.y - prevVel.y) / dt;
        const az_meas = (v.z - prevVel.z) / dt;

        const r_avg = 0.5 * (att.roll + prevAtt.roll);
        const p_avg = 0.5 * (att.pitch + prevAtt.pitch);
        const y_avg = 0.5 * (att.yaw + prevAtt.yaw);
        const bodyX = Math.sin(p_avg) * Math.cos(r_avg);
        const bodyZ = -Math.sin(r_avg);
        const dirX = Math.cos(y_avg) * bodyX + Math.sin(y_avg) * bodyZ;
        const dirY = Math.cos(p_avg) * Math.cos(r_avg);
        const dirZ = -Math.sin(y_avg) * bodyX + Math.cos(y_avg) * bodyZ;

        const actual_spec = clamp((ay_meas + 9.81 + (0.42 / estMass) * v.y) / Math.max(0.55, dirY), 2.0, 22.0);
        const ax_model = actual_spec * dirX - (0.42 / estMass) * v.x;
        const ay_model = estSpec * dirY - 9.81 - (0.42 / estMass) * v.y;
        const az_model = actual_spec * dirZ - (0.42 / estMass) * v.z;

        const alpha = 0.20;
        distX = clamp(distX + alpha * ((ax_meas - ax_model) - distX), -7.5, 7.5);
        distY = clamp(distY + 0.08 * ((ay_meas - ay_model) - distY), -4.0, 4.0);
        distZ = clamp(distZ + alpha * ((az_meas - az_model) - distZ), -7.5, 7.5);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };

      let target;
      let vx_ref = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        const vy = Math.abs(vyFilt);
        const vz = Math.abs(vzFilt);

        const distToGateX = Math.max(0, gate.x - p.x);
        const tToGate = clamp(distToGateX / Math.max(0.45, vxFilt), 0.03, 0.20);
        const predZ = Math.abs((p.z + vzFilt * tToGate) - gate.z);
        const predY = Math.abs((p.y + vyFilt * tToGate) - gate.y);

        if (phase === 'align') {
          const approachX = gate.x - 0.35;
          target = { x: approachX, y: gate.y, z: gate.z };
          if (p.x > gate.x - 0.55 && p.x < gate.x - 0.05 && dy < 0.075 && dz < 0.022 && predZ < 0.024 && predY < 0.085 && vy < 0.30 && vz < 0.16) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 4) phase = 'cross';
        }
        if (phase === 'cross') {
          target = { x: gate.x + 0.38, y: gate.y, z: gate.z };
          vx_ref = 0.70;
          if (p.x < gate.x - 0.12 && (dy > 0.10 || dz > 0.026 || predZ > 0.030)) {
            phase = 'align';
            settle = 0;
            vx_ref = 0;
